static uint16_t io=0;static bool nic=false;static uint8_t mac[6]{};static uint8_t gateway_mac[6]{};static bool gateway_known=false;static bool ping_reply=false;static constexpr uint32_t IP=(10u<<24)|(0u<<16)|(2u<<8)|15u;static constexpr uint32_t GW=(10u<<24)|(0u<<16)|(2u<<8)|2u;alignas(256) static uint8_t rxbuf[8192+16+1500];alignas(16) static uint8_t txbuf[4][2048];static uint16_t rxpos=0;static uint8_t txslot=0;
static uint16_t be16(const uint8_t* p){return (uint16_t)((p[0]<<8)|p[1]);}static uint32_t be32(const uint8_t* p){return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}static void put16(uint8_t* p,uint16_t v){p[0]=(uint8_t)(v>>8);p[1]=(uint8_t)v;}static void put32(uint8_t* p,uint32_t v){p[0]=(uint8_t)(v>>24);p[1]=(uint8_t)(v>>16);p[2]=(uint8_t)(v>>8);p[3]=(uint8_t)v;}static uint16_t csum(const uint8_t* p,size_t n){uint32_t s=0;while(n>1){s+=((uint16_t)p[0]<<8)|p[1];p+=2;n-=2;}if(n)s+=(uint16_t)p[0]<<8;while(s>>16)s=(s&0xFFFF)+(s>>16);return (uint16_t)~s;}static void mac_copy(uint8_t* d,const uint8_t* s){for(int i=0;i<6;++i)d[i]=s[i];}static bool mac_eq(const uint8_t* a,const uint8_t* b){for(int i=0;i<6;++i)if(a[i]!=b[i])return false;return true;}
static bool rtl_tx(const uint8_t* data,uint16_t len){if(!nic||len>2000)return false;uint8_t s=txslot++&3;ir::memcpy(txbuf[s],data,len);io_out32(io+0x20+s*4,(uint32_t)(uint64_t)&txbuf[s][0]);io_out32(io+0x10+s*4,len);return true;}static uint16_t ring16(uint16_t pos){uint16_t a=rxbuf[pos&8191];uint16_t b=rxbuf[(pos+1)&8191];return (uint16_t)(a|(b<<8));}static int rtl_rx(uint8_t* out,int cap){if(!nic||(io_in8(io+0x37)&1))return 0;uint16_t status=ring16(rxpos),len=ring16((uint16_t)(rxpos+2));if(!(status&1)||len<4||len>1800){rxpos=0;io_out16(io+0x38,0xFFF0);io_out16(io+0x3E,0xFFFF);return 0;}int payload=(int)len-4;if(payload>cap)payload=cap;for(int i=0;i<payload;++i)out[i]=rxbuf[(rxpos+4+i)&8191];rxpos=(uint16_t)((rxpos+len+4+3)&~3u);rxpos&=8191;io_out16(io+0x38,(uint16_t)(rxpos-16));io_out16(io+0x3E,0xFFFF);return payload;}
static void ethernet(uint8_t* f,const uint8_t* dst,uint16_t type){mac_copy(f,dst);mac_copy(f+6,mac);put16(f+12,type);}static void arp_request(){uint8_t f[64];for(auto& b:f)b=0;uint8_t bc[6]={255,255,255,255,255,255};ethernet(f,bc,0x0806);put16(f+14,1);put16(f+16,0x0800);f[18]=6;f[19]=4;put16(f+20,1);mac_copy(f+22,mac);put32(f+28,IP);put32(f+38,GW);rtl_tx(f,60);}static void arp_reply(const uint8_t* req){uint8_t f[64];for(auto& b:f)b=0;ethernet(f,req+22,0x0806);put16(f+14,1);put16(f+16,0x0800);f[18]=6;f[19]=4;put16(f+20,2);mac_copy(f+22,mac);put32(f+28,IP);mac_copy(f+32,req+22);put32(f+38,be32(req+28));rtl_tx(f,60);}static void handle_arp(const uint8_t* p,int n){if(n<28||be16(p)!=1||be16(p+2)!=0x0800||p[4]!=6||p[5]!=4)return;uint16_t op=be16(p+6);uint32_t sip=be32(p+14),tip=be32(p+24);if(sip==GW){mac_copy(gateway_mac,p+8);gateway_known=true;}if(op==1&&tip==IP)arp_reply(p);}static void handle_ipv4(const uint8_t* p,int n){if(n<20||(p[0]>>4)!=4)return;int ihl=(p[0]&15)*4;if(ihl<20||n<ihl)return;if(be32(p+16)!=IP)return;if(p[9]==1&&n>=ihl+8){const uint8_t* ic=p+ihl;if(ic[0]==0&&be16(ic+4)==0x4952)ping_reply=true;}}static void handle_frame(const uint8_t* f,int n){if(n<14)return;if(!mac_eq(f,mac)){bool bc=true;for(int i=0;i<6;++i)if(f[i]!=255)bc=false;if(!bc)return;}uint16_t t=be16(f+12);if(t==0x0806)handle_arp(f+14,n-14);else if(t==0x0800)handle_ipv4(f+14,n-14);}
bool init(){auto d=pci::find(0x10EC,0x8139);if(!d.found){arch::serial_print("net: rtl8139 not found\n");return false;}pci::enable_io_busmaster(d);io=(uint16_t)(d.bar0&~3u);if(!io)return false;io_out8(io+0x52,0x00);io_out8(io+0x37,0x10);for(int i=0;i<100000&&io_in8(io+0x37)&0x10;++i){}for(int i=0;i<6;++i)mac[i]=io_in8(io+i);io_out32(io+0x30,(uint32_t)(uint64_t)&rxbuf[0]);io_out16(io+0x3C,0);io_out32(io+0x44,0x0000008Fu);io_out8(io+0x37,0x0C);rxpos=0;io_out16(io+0x38,0xFFF0);io_out16(io+0x3E,0xFFFF);nic=true;arp_request();arch::serial_print("net: rtl8139 polling stack online 10.0.2.15\n");return true;}void service(){if(!nic)return;uint8_t frame[1700];for(int i=0;i<8;++i){int n=rtl_rx(frame,sizeof(frame));if(n<=0)break;handle_frame(frame,n);}}bool online(){return nic;}bool link_ready(){return nic&&gateway_known;}
bool ping_gateway(){if(!nic)return false;if(!gateway_known){arp_request();uint64_t until=arch::ticks()+200;while(arch::ticks()<until&&!gateway_known){service();asm volatile("pause");}}if(!gateway_known)return false;uint8_t f[64];for(auto& b:f)b=0;ethernet(f,gateway_mac,0x0800);uint8_t* ip=f+14;ip[0]=0x45;put16(ip+2,28);put16(ip+4,0x4952);ip[8]=64;ip[9]=1;put32(ip+12,IP);put32(ip+16,GW);put16(ip+10,csum(ip,20));uint8_t* ic=ip+20;ic[0]=8;put16(ic+4,0x4952);put16(ic+6,1);put16(ic+2,csum(ic,8));ping_reply=false;rtl_tx(f,60);uint64_t until=arch::ticks()+200;while(arch::ticks()<until&&!ping_reply){service();asm volatile("pause");}return ping_reply;}const char* ip_string(){return "10.0.2.15";}const char* mac_string(){static char s[18];const char* h="0123456789ABCDEF";for(int i=0;i<6;++i){s[i*3]=h[mac[i]>>4];s[i*3+1]=h[mac[i]&15];if(i<5)s[i*3+2]=':';}s[17]=0;return s;}
